import{state}from"./state.js";import{renderAll,renderRequests}from"./ui.js";import{showToast,showConfirm,showMobileEventNotification}from"./utils.js";import{scheduleSave,addHistoryEntry,checkLimits,checkFrequency,checkDailyCoinLimit,updateBalanceLocally}from"./action-helpers.js";import{triggerCoinBurst}from"./motion-feedback.js";function verifyPurchaseLimits(e,i,t){if(!i)return t();const s=checkLimits(i,e.moneyAmount||0,{childIdOverride:e.childId,excludeRequestId:e.id});if(s){const i=`${s}<br><br>Списать ${e.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.1rem; height: 1.1rem; vertical-align: middle;"></span>?`;showConfirm("Лимит превышен",i,{onConfirm:t})}else t()}function finalizeRequest(e,i){if(!e)return null;const t={...e,status:i,resolvedAt:(new Date).toISOString()};return state.requests=state.requests.map(i=>i.id==e.id?t:i),scheduleSave(),t}function handleApprovePurchase(e){const i=state.children.find(i=>i.id==e.childId);if(i&&i.balance<e.coins)return showToast(`Недостаточно монет у ребенка (${i.name})`,"error");const t=state.shopItems.find(i=>i.id==(e.itemId||e.taskId));verifyPurchaseLimits(e,t,()=>{updateBalanceLocally(e.childId,-e.coins),addHistoryEntry({type:"spend",amount:e.coins,description:e.taskName||"Покупка",group:t?t.group:void 0,comment:t?t.comment:void 0,relatedId:e.itemId||e.taskId,moneyAmount:e.moneyAmount||0,childIdOverride:e.childId}),finalizeRequest(e,"approved"),renderAll(),triggerCoinBurst()})}function handleApproveTask(e){const i=state.tasks.find(i=>i.id==e.taskId&&(!i.childId||i.childId==e.childId)),t=[];if(i){const s=checkFrequency(i,e.childId,e.id);s&&t.push(s)}const s=checkDailyCoinLimit(e.childId,e.coins,e.id);s&&t.push(s);const n=()=>{updateBalanceLocally(e.childId,e.coins);const t=i?i.name:e.taskName;addHistoryEntry({type:"earn",amount:e.coins,description:t,group:i?i.group:void 0,comment:i?i.comment:void 0,relatedId:e.taskId,childIdOverride:e.childId}),finalizeRequest(e,"approved"),renderAll(),showMobileEventNotification(`Заявка подтверждена: +${e.coins} мон.`,"success","Заявка подтверждена"),triggerCoinBurst()};if(t.length>0){const i=`${t.join(". ")}<br><br>Начислить ${e.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.1rem; height: 1.1rem; vertical-align: middle;"></span>?`;showConfirm("Лимиты превышены",i,{onConfirm:n})}else n()}export function approveRequest(e){const i=state.requests.find(i=>i.id==e);if(!i)return;"shop_purchase"===i.requestType?handleApprovePurchase(i):handleApproveTask(i)}export function rejectRequest(e){const i=state.requests.find(i=>i.id==e);i&&(finalizeRequest(i,"rejected"),renderRequests(),showToast("Заявка отклонена","info"))}export function deleteRequest(e){showConfirm("Удалить заявку?","Вы уверены, что хотите безвозвратно удалить заявку?",{onConfirm:()=>{state.requests=state.requests.filter(i=>i.id!=e),scheduleSave(),renderRequests()}})}